DROP TABLE IF EXISTS `loan_applications`;
CREATE TABLE `loan_applications` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'application_id',
  `borrower_id` int(11) DEFAULT NULL,
  `request_date` date NOT NULL,
  `loan_id` int(10) DEFAULT NULL,
  `request_amount` decimal(10,2) DEFAULT 0.00,
  `principal` decimal(10,2) NOT NULL DEFAULT 0.00,
  `status_id` tinyint(6) NOT NULL DEFAULT 1,
  `referrer_id` int(10) DEFAULT NULL COMMENT 'person_id',
  `remarks` varchar(100) DEFAULT NULL,
  `estimated_net_monthly_income` decimal(10,2) NOT NULL DEFAULT 0.00,
  `branch_id` int(10) DEFAULT NULL,
  `purpose_id` int(10) DEFAULT NULL,
  `create_user` varchar(35) DEFAULT NULL,
  `create_date` timestamp(6) NULL DEFAULT NULL ON UPDATE current_timestamp(6),
  `code` varchar(25) DEFAULT '0',
  `period_interest_rate` decimal(10,2) DEFAULT 0.00,
  `monthly_interest_rate` decimal(10,2) DEFAULT 0.00,
  `period_months` decimal(10,2) DEFAULT 0.00 COMMENT 'period in months',
  `loan_tenure` decimal(10,2) DEFAULT NULL COMMENT 'loan period can be in day,week, month, year',
  `payback_method_id` tinyint(6) DEFAULT 0,
  `auth_user` varchar(35) DEFAULT NULL,
  `auth_date` time DEFAULT NULL,
  `minimum_installment` decimal(10,2) DEFAULT 0.00,
  `loan_type_id` tinyint(6) NOT NULL DEFAULT 1,
  `price_loan_percentage` decimal(10,2) DEFAULT 0.00,
  `item_full_price` decimal(10,2) DEFAULT 0.00,
  `disburse_user` varchar(35) DEFAULT NULL,
  `disburse_date` timestamp(6) NULL DEFAULT NULL ON UPDATE current_timestamp(6),
  `admin_fee` decimal(10,2) DEFAULT 0.00,
  `cbc_fee` decimal(10,2) DEFAULT 0.00,
  `laywer_fee` decimal(10,2) DEFAULT 0.00,
  `inactive` tinyint(6) NOT NULL DEFAULT 0,
  `special_remarks` varchar(350) DEFAULT NULL,
  `first_pmt_date` date DEFAULT NULL,
  `program_id` int(11) DEFAULT NULL,
  `student_code` varchar(35) DEFAULT NULL,
  `CGPA` decimal(10,2) DEFAULT NULL,
  `lawyer_fee` decimal(10,2) DEFAULT 0.00,
  `create_uid` int(11) DEFAULT 0,
  `update_uid` int(11) DEFAULT NULL,
  `update_user` varchar(50) DEFAULT NULL,
  `update_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `start_date` date DEFAULT NULL,
  `compound_cycle` varchar(15) DEFAULT NULL,
  `currency_code` varchar(10) DEFAULT NULL,
  `loan_tenure_unit` varchar(15) DEFAULT NULL COMMENT 'loan_tenure_unit = {days,weeks,months,years}',
  `period_count` decimal(10,2) DEFAULT 0.00,
  `credit_officer_id` int(11) DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2030 DEFAULT CHARSET=utf8mb4;

