-- ----------------------------
-- Function structure for `format_loan_code`
-- ----------------------------
DROP FUNCTION IF EXISTS `format_loan_code`;
DELIMITER ;;
CREATE   FUNCTION `format_loan_code`(num INT) RETURNS varchar(20) CHARSET utf8mb4
BEGIN
 RETURN CONCAT(substr('100000',1,6 - length(num)),num);
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `format_receipt_number`
-- ----------------------------
DROP FUNCTION IF EXISTS `format_receipt_number`;
DELIMITER ;;
CREATE   FUNCTION `format_receipt_number`(num INT) RETURNS varchar(20) CHARSET utf8mb4
BEGIN
 RETURN CONCAT(substr('1000000',1,7 - length(num)),num);
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `getAcademicProgram`
-- ----------------------------
DROP FUNCTION IF EXISTS `getAcademicProgram`;
DELIMITER ;;
CREATE   FUNCTION `getAcademicProgram`(loanid INT) RETURNS varchar(150) CHARSET utf8mb4
BEGIN
  DECLARE prog_name varchar(150);
  SET prog_name = (SELECT prog.`name` FROM loans AS l INNER JOIN academic_programs AS prog ON l.program_id = prog.id WHERE l.id =loanid LIMIT 1);
  RETURN prog_name;
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `getCurSymbol`
-- ----------------------------
DROP FUNCTION IF EXISTS `getCurSymbol`;
DELIMITER ;;
CREATE   FUNCTION `getCurSymbol`(cur_code varchar(15),def_symbol varchar(5)) RETURNS varchar(10) CHARSET utf8mb4
BEGIN
  SET @cur_symbol = (select symbol from currencies as c WHERE c.`code` =cur_code LIMIT 1);
  return IFNULL(@cur_symbol,def_symbol);
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `has_collateral`
-- ----------------------------
DROP FUNCTION IF EXISTS `has_collateral`;
DELIMITER ;;
CREATE   FUNCTION `has_collateral`(branchid INT, appid INT) RETURNS tinyint(4)
BEGIN
  DECLARE has_coll tinyint;
  SET has_coll =0;
  IF exists(select id from collaterals as c where c.branch_id = branchid AND c.loan_app_id = appid LIMIT 1) THEN
    SET has_coll =1;
  END IF;
  RETURN has_coll;  
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `has_paid`
-- ----------------------------
DROP FUNCTION IF EXISTS `has_paid`;
DELIMITER ;;
CREATE   FUNCTION `has_paid`(branchid int, loanid int, startdate varchar(30), enddate varchar(30)) RETURNS tinyint(4)
BEGIN
   IF ((DATE(startdate) IS NULL) OR (DATE(enddate) IS NULL)) THEN
     IF EXISTS (SELECT c.id FROM loan_collections AS c WHERE c.branch_id = branchid AND c.pmt_type ='installment' AND IFNULL(c.inactive,0)=0 AND c.loan_id =loanid AND c.amount > 0 LIMIT 1) THEN
         return 1;
     ELSE
         return 0;  
     END IF;

  ELSE 
   
     IF EXISTS (SELECT c.id FROM loan_collections AS c WHERE c.branch_id =branchid AND c.pmt_type ='installment' AND IFNULL(c.inactive,0) =0 AND c.loan_id =loanid AND c.amount > 0 AND (DATE(c.payment_date) >=startdate AND DATE(c.payment_date) <=enddate) LIMIT 1) THEN 
         return 1;
     ELSE
         return 0;  
     END IF;
  
  END IF;
 
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `has_prn`
-- ----------------------------
DROP FUNCTION IF EXISTS `has_prn`;
DELIMITER ;;
CREATE   FUNCTION `has_prn`(roleid int, prnid int) RETURNS tinyint(4)
BEGIN
  IF EXISTS(SELECT rp.permission_id FROM um_role_permissions as rp WHERE rp.role_id =roleid and rp.permission_id = prnid limit 1) THEN 
      return 1;
  ELSE return 0;
  end if;  

END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for `is_read`
-- ----------------------------
DROP FUNCTION IF EXISTS `is_read`;
DELIMITER ;;
CREATE   FUNCTION `is_read`(id int,userid int) RETURNS tinyint(4)
BEGIN 
  return exists(SELECT id FROM notification_reads WHERE user_id =userid AND notif_id = id LIMIT 1);
END
;;
DELIMITER ;
